// Parse le JSON de l'Agent 1
const raw = $input.first().json.output || "";
let params;
try {
  const cleaned = raw.replace(/```json/gi, "").replace(/```/g, "").trim();
  params = JSON.parse(cleaned);
} catch(e) {
  params = { secteur: "transport", zone: "france", departement: null, type_graphique: "bar", zone_label: "Toute la France" };
}

const zone        = params.zone        || "france";
const secteur     = params.secteur     || "transport";
const departement = params.departement || null;
const type_graphique = params.type_graphique || "bar";
const type_question  = params.type_question  || "volume";
const zone_label     = params.zone_label     || "Toute la France";
const question = $('Webhook').first().json.body.question || "";

// Détermine si on filtre par département dans l'API
const use_dept = departement && zone !== "france" && zone !== "idf";

return [{ json: {
  question, secteur, zone, departement, use_dept,
  type_graphique, type_question, zone_label,
  params_ia: params
}}];

