const stats    = $('Code in JavaScript').first().json;
const analyse  = $('Agent 2 — Analyse').first().json.output || "Analyse non disponible.";
const question = $('Webhook').first().json.body.question || "";
const params   = stats.params_ia || {};

const top_departements = stats.top_departements || [];
const top_secteurs     = stats.top_secteurs     || [];
const top_communes     = stats.top_communes     || [];
const n_total          = stats.n_total          || 0;
const secteur          = stats.secteur          || "";
const zone_label       = stats.zone_label       || "France";
const type_graphique   = stats.type_graphique   || "bar";

const top1     = top_departements[0] || {};
const top_ape1 = top_secteurs[0]     || {};

const viz = {
  type_graphique, secteur, zone_label,
  bar:     { titre: `Entreprises "${secteur}" — ${zone_label}`, data: top_departements.map(d => ({ label: d.nom || d.departement, value: d.nb_entreprises })) },
  treemap: { titre: `Secteurs APE — "${secteur}"`, data: top_secteurs.map(s => ({ label: s.label, value: s.nb_entreprises })) },
  pie:     { titre: `Répartition — "${secteur}"`, data: top_departements.slice(0,8).map(d => ({ label: d.nom || d.departement, value: d.nb_entreprises })) },
  commune: { titre: `Top communes — "${secteur}"`, data: top_communes.map(c => ({ label: c.commune, value: c.nb_entreprises })) }
};

return [{ json: {
  analyse, n_total, zone_label, secteur, question,
  kpi: {
    n_total,
    n_departements: top_departements.length,
    top_dept_nom:   top1.nom || top1.departement || "—",
    top_dept_nb:    top1.nb_entreprises || 0,
    top_ape_label:  top_ape1.label || "—",
    top_ape_nb:     top_ape1.nb_entreprises || 0
  },
  top_departements, top_secteurs, top_communes,
  viz, params_ia: params,
  generated_at: new Date().toISOString()
}}];

const params      = $input.first().json;
const secteur     = params.secteur     || "transport";
const zone        = params.zone        || "france";
const use_dept    = params.use_dept    || false;
const departement = params.departement || null;
const MCP_URL     = "http://127.0.0.1:8000/mcp";

// Parse la réponse SSE string → companies[]
function parseSSECompanies(raw) {
  const dataLine = String(raw).split("\n").find(l => l.trim().startsWith("data:"));
  if (!dataLine) return [];
  try {
    const json    = JSON.parse(dataLine.replace(/^data:\s*/, "").trim());
    const text    = json?.result?.content?.[0]?.text || "{}";
    const data    = JSON.parse(text);
    return data.companies || [];
  } catch(e) { return []; }
}

function parseSSEStats(raw) {
  const dataLine = String(raw).split("\n").find(l => l.trim().startsWith("data:"));
  if (!dataLine) return {};
  try {
    const json = JSON.parse(dataLine.replace(/^data:\s*/, "").trim());
    const text = json?.result?.content?.[0]?.text || "{}";
    return JSON.parse(text);
  } catch(e) { return {}; }
}

async function callMCP(toolName, args) {
  return await this.helpers.httpRequest({
    method: "POST", url: MCP_URL,
    headers: { "Content-Type": "application/json", "Accept": "application/json, text/event-stream" },
    body: JSON.stringify({ jsonrpc:"2.0", id:1, method:"tools/call", params:{ name:toolName, arguments:args } }),
    returnFullResponse: false
  });
}

// Étape 1 : search_companies
const r1 = await callMCP.call(this, "search_companies", {
  query: secteur,
  departement: (use_dept && departement) ? String(departement) : "",
  per_page: 25
});
const companies = parseSSECompanies(r1);

// Étape 2 : filter_by_geography
const r2 = await callMCP.call(this, "filter_by_geography", {
  companies_json: JSON.stringify({ companies }),
  zone: zone
});
const filtered = parseSSECompanies(r2).length > 0 
  ? parseSSECompanies(r2) 
  : (() => { try { return JSON.parse(parseSSEStats(r2).companies ? JSON.stringify(parseSSEStats(r2).companies) : "[]"); } catch(e) { return companies; } })();

// Étape 3 : compute_statistics
const r3 = await callMCP.call(this, "compute_statistics", {
  companies_json: JSON.stringify({ companies: filtered.length > 0 ? filtered : companies }),
  top_n: 10
});
const stats = parseSSEStats(r3);
const toArr = v => Array.isArray(v) ? v : [];

return [{ json: {
  n_total:          stats.n_total          || 0,
  top_departements: toArr(stats.top_departements),
  top_secteurs:     toArr(stats.top_secteurs),
  top_communes:     toArr(stats.top_communes),
  zone:             params.zone,
  zone_label:       params.zone_label,
  secteur:          params.secteur,
  type_graphique:   params.type_graphique,
  type_question:    params.type_question,
  params_ia:        params.params_ia
}}];
